function decideBranch(fetchResult) {
  if (fetchResult.items.length === 0) return "no_results";
  if (fetchResult.items.length > 50) return "too_many_results";
  return "normal";
}

async function runStep(step, context, mcpClient) {
  if (step.toolName) {
    const result = await mcpClient.callTool(step.toolName, step.toolArgs(context));
    context.results[step.name] = result;
  }
  return context;
}

const workflow = [
  { name: "plan", type: "task", run: planStep },
  { name: "fetch_data", type: "task", run: fetchDataStep },
  { name: "check_results", type: "branch", run: checkResultsBranch },
  { name: "retry_fetch", type: "task", run: fetchDataStep },
  { name: "summarize", type: "task", run: summarizeStep }
];

async function runWorkflow(workflow, context, onStepChange) {
  let currentIndex = 0;
  let loopCount = 0;
  while (currentIndex < workflow.length) {
    const step = workflow[currentIndex];
    onStepChange({ step: step.name, status: "running" });

    const outcome = await step.run(context);
    context.results[step.name] = outcome;
    onStepChange({ step: step.name, status: "done" });

    if (step.type === "branch" && outcome.goto) {
      currentIndex = workflow.findIndex((s) => s.name === outcome.goto);
      loopCount += 1;
      if (loopCount > 10) throw new Error("loop cap exceeded");
      continue;
    }
    currentIndex += 1;
  }
  return context;
}

async function fetchDataStep(context) {
  const result = await mcpClient.callTool("search_tickets", {
    query: context.results.plan.query
  });
  return { items: result.items };
}

function checkResultsBranch(context) {
  const items = context.results.fetch_data.items;
  if (items.length === 0) return { goto: "retry_fetch" };
  return { goto: "summarize" };
}

function logStep(event) {
  console.log(JSON.stringify({
    ts: new Date().toISOString(),
    step: event.step,
    status: event.status
  }));
}
// runWorkflow(workflow, context, logStep);

async function fetchDataStep(context) {
  try {
    const result = await mcpClient.callTool("search_tickets", {
      query: context.results.plan.query
    });
    return { items: result.items, error: null };
  } catch (err) {
    return { items: [], error: err.message };
  }
}

const supportWorkflow = [
  { name: "plan", type: "task", run: planStep },
  { name: "fetch_ticket", type: "task", run: fetchTicketStep },
  { name: "check_ticket", type: "branch", run: checkTicketBranch },
  { name: "summarize", type: "task", run: summarizeTicketStep }
];

async function planStep(context) {
  return { query: context.userRequest.trim() };
}

async function fetchTicketStep(context) {
  const result = await mcpClient.callTool("get_ticket", {
    id: context.results.plan.query
  });
  return { ticket: result.ticket };
}

function checkTicketBranch(context) {
  if (!context.results.fetch_ticket.ticket) return { goto: "fetch_ticket" };
  return { goto: "summarize" };
}

async function summarizeTicketStep(context) {
  const t = context.results.fetch_ticket.ticket;
  return { text: "Ticket " + t.id + " is currently " + t.status };
}
